  "b2.farule1": "खाताको ह्रासकट्टी भारतको कम्पनीज एक्ट, 2013 को सेड्युल II अनुसार छ: हरेक किसिमको एसेटको प्रयोग अवधि हुन्छ (जस्तै कम्प्युटर 3 वर्ष, फर्निचर 10 वर्ष, प्लान्ट र मेसिनरी 15 वर्ष, कार 8 वर्ष), बाँकी मूल्य प्रायः मूल्यको 5% भन्दा बढी हुँदैन, र वर्षको बीचमा थपिएको वा बेचिएको एसेटमा प्रयोग भएका दिनको मात्र ह्रासकट्टी लाग्छ। स्ट्रेट लाइन (SLM: हरेक वर्ष बराबर रकम) वा रिटन डाउन भ्यालु (WDV: बाँकी रकममा तोकिएको रेट) छान्नुहोस्। प्रोप्राइटर र फर्महरूले प्रायः यही तरिका अपनाउँछन्; निर्णय तपाईंको एकाउन्टेन्टको हो।",
  "b2.farule2": "आयकर ह्रासकट्टी हरेक ब्लकको छुट्टै निकालिन्छ: ब्लक रेटमा रिटन डाउन भ्यालु (जस्तै प्लान्ट र मेसिनरी 15%, फर्निचर 10%, कम्प्युटर 40%), वर्षमा 180 दिनभन्दा कम प्रयोग भएको एसेटमा आधा रेट, र बिक्रीको पैसा ब्लकबाट घट्छ। यो आयकर रिटर्नको लागि मात्र हो, खातामा कहिल्यै हालिँदैन। भरिएका रेटहरू सामान्य ब्लक रेट हुन्: आफ्नो एकाउन्टेन्टसँग पक्का गर्नुहोस्, विशेषगरी 1 अप्रिल 2026 देखि भारतको इन्कम-ट्याक्स एक्ट, 2025 अन्तर्गतका वर्षहरूको लागि।",
  "b2.farule3": "तपाईंले 'ह्रासकट्टी हाल्नुहोस्' थिचेपछि मात्र ह्रासकट्टी खातामा जान्छ: वर्षको अन्तिम दिनको (वा वर्षको बीचमा आजको) जर्नल इन्ट्रीले ह्रासकट्टीलाई डेबिट गर्छ र हरेक एसेट घटाउँछ। पछि एसेट बदले फेरि हाल्नुहोस्, फरक मात्र थपिन्छ।",
