  "it.f_def_h": "अहिलेसम्म नकमाएको क्यापिटल गेन, जितेको रकम, डिभिडेन्ड वा पहिलो वर्षको व्यवसायको नाफा: बाँकी किस्तामा तिरेमा अघिल्ला किस्तामा गनिँदैन (section 425(4))।",
  "it.f_mon": "कर कम भए ब्याजका महिना",
  "it.f_mon_h": "वर्षपछिको 1 April देखि रिटर्न प्रोसेस भएको दिनसम्म। 4 = 31 July भित्र भरिएको रिटर्न।",
  "it.m_senior": "व्यवसाय वा पेसाको आम्दानी नभएका 60 वर्ष वा बढी उमेरका बासिन्दाले अग्रिम कर तिर्दैनन् (section 403(3))। बाँकी रिटर्न भर्दा तिर्नुहोस्।",
  "it.m_below": "TDS पछिको कर {n} छ, ₹10,000 भन्दा कम, त्यसैले अग्रिम कर लाग्दैन (section 404)। बाँकी रिटर्न भर्दा तिर्नुहोस्।",
  "it.m_pres": "अनुमानित योजनामा पूरा अग्रिम कर 15 March वा त्योभन्दा अघि तिरिन्छ (section 408(2))।",
  "it.m_sur": "तपाईंको आम्दानी ₹50 लाखभन्दा बढी छ: सरचार्ज टाइप गर्नुहोस्, यहाँ निकालिँदैन।",
  "it.m_past": "यो वर्ष सकियो। 31 March पछि तिरेको अग्रिम कर यो वर्षको अग्रिम करमा गनिँदैन; तलको ब्याजले कमीको खर्च देखाउँछ।",
  "it.m_season": "अनुमानले अहिलेसम्मको नाफालाई सिधा हिसाबले पूरा वर्षमा पुर्‍याउँछ। तपाईंको व्यवसाय मौसमी भए वर्षको आफ्नै रकम टाइप गर्नुहोस्।",
