  "it.basis": "यी रकम केमा आधारित छन् ({d} सम्मको)",
  "it.b1": "दर ({d} सम्मको), कर वर्ष 2026-27: नयाँ रिजिम ₹4 लाखसम्म शून्य, ₹8 लाखसम्म 5%, ₹12 लाखसम्म 10%, ₹16 लाखसम्म 15%, ₹20 लाखसम्म 20%, ₹24 लाखसम्म 25%, माथि 30%; ₹12 लाखसम्मको आम्दानीमा कर नलाग्ने गरी रिबेट, त्योभन्दा अलि माथि मार्जिनल रिलिफ; तलबमा स्ट्यान्डर्ड डिडक्सन ₹75,000। पुरानो रिजिम: ₹2.5 लाखसम्म शून्य (60 मा ₹3 लाख, 80 मा ₹5 लाख), ₹5 लाखसम्म 5%, ₹10 लाखसम्म 20%, माथि 30%; ₹5 लाखसम्म ₹12,500 रिबेट; स्ट्यान्डर्ड डिडक्सन ₹50,000। यी दर सेलरी स्लिप टुलले पहिले नै प्रयोग गर्ने दर हुन्; यो बनाउँदा Finance Act बाट फेरि पढिएनन्, त्यसैले जाँच गर्नुहोस्।",
  "it.b2": "अग्रिम कर (Income-tax Act 2025, sections 403 देखि 408): TDS पछिको कर ₹10,000 वा बढी हुँदा लाग्छ; 15 June सम्म 15%, 15 September सम्म 45%, 15 December सम्म 75%, 15 March सम्म सबै; अनुमानित करदाताले 15 March सम्म सबै तिर्छन्; 31 March सम्मको भुक्तानी त्यो वर्षमा गनिन्छ; व्यवसायको आम्दानी नभएका 60 वर्ष वा बढी उमेरका बासिन्दालाई छुट छ।",
  "it.b3": "ब्याज: section 424 (पुरानो 234B) मा करको 90% भन्दा कम तिरिए कमीमा हरेक महिना वा महिनाको भागका लागि 1%; section 425 (पुरानो 234C) मा पहिला तीन किस्ताको हरेकको कमीमा 3% (15 June सम्म 12% र 15 September सम्म 36% तिरिए लाग्दैन) र March को कमीमा 1%।",
  "it.b4": "माथिका section 15 Nov 2026 मा Income Tax Department को वेबसाइट (incometaxindia.gov.in) को आधिकारिक पाठसँग शब्द-शब्द जाँचिएका थिए। छापिएको Act नै मान्य हुन्छ।",
  "it.b5": "खाताको नाफा करयोग्य नाफा होइन: Act अनुसारको ह्रास, अस्वीकृत खर्च र अनुमानित नियमले यसलाई बदल्छन्। यो प्लान र डेटा पाना आफ्नो एकाउन्टेन्टलाई दिनुहोस्।",
  "it.b6": "निकालिँदैन: सरचार्ज, विशेष दरको क्यापिटल गेन, विदेशी कर राहत, नाबालकको आम्दानीमा कर, र ढिलो रिटर्नको ब्याज।",
  "it.b7": "केही पनि फाइल हुँदैन र तपाईंको खातामा केही चढ्दैन।",
