  "it.formd_ITR-1": "तलब वा पेन्सन, दुईवटासम्म घर सम्पत्ति र ब्याज जस्ता अरू स्रोत भएका, जम्मा आम्दानी ₹50 लाखसम्म भएका बासिन्दा व्यक्तिका लागि।",
  "it.formd_ITR-2": "व्यवसाय वा पेसाको आम्दानी नभएका, क्यापिटल गेन भएका, ₹50 लाखभन्दा बढी आम्दानी, दुईभन्दा बढी घर सम्पत्ति, विदेशी सम्पत्ति वा आम्दानी भएका, वा ITR-1 मा नमिल्ने व्यक्ति वा HUF का लागि।",
  "it.formd_ITR-3": "अनुमानित योजनामा नभएको व्यवसाय वा पेसाको आम्दानी भएका व्यक्ति वा HUF, फर्मका साझेदार, वा ITR-4 मा नमिल्ने जोकोहीका लागि।",
  "it.formd_ITR-4": "अनुमानित व्यवसायको आम्दानी, ₹50 लाखसम्म जम्मा आम्दानी, तलब वा पेन्सन, दुईवटासम्म घर सम्पत्ति र अरू स्रोत भएका बासिन्दा व्यक्ति वा HUF का लागि।",
  "it.formd_ITR-5": "फर्म, LLP, व्यक्तिहरूको सङ्घ र व्यक्तिहरूको निकायका लागि।",
  "it.formd_ITR-6": "धार्मिक वा परोपकारी प्रयोजनका लागि छुट दाबी गर्नेबाहेकका कम्पनीका लागि।",
  "it.formd_ITR-7": "ट्रस्ट, संस्था, राजनीतिक दल र यस्तै व्यक्तिका लागि।",
