  "it.w_over50": "₹50 लाखभन्दा बढी जम्मा आम्दानी भए ITR-1 र ITR-4 मिल्दैनन्।",
  "it.w_capgain": "सूचीकृत सेयरको सानो सीमाबाहेकको क्यापिटल गेनका लागि ITR-2 वा ITR-3 चाहिन्छ।",
