  "it.w_huf": "ITR-1 व्यक्तिका लागि मात्र हो; व्यवसायको आम्दानी नभएको HUF ले ITR-2 भर्छ।",
  "it.w_pres2": "तपाईंका अरू जवाफले ITR-4 मिल्दैन, त्यसैले व्यवसायको आम्दानी ITR-3 मा जान्छ।",
  "it.w_pres": "अनुमानित व्यवसायको आम्दानी र साधारण अरू आम्दानी ITR-4 मा मिल्छ।",
  "it.w_simple": "सीमाभित्रको तलब, घर सम्पत्ति र ब्याज मात्र भए ITR-1 मा मिल्छ।",
  "it.n_forms": "सर्तहरू 31 March 2026 मा सकिएको वर्षका लागि सूचित रिटर्नअनुसार छन् (ट्याक्स पोर्टलहरूका अनुसार ITR-1 र ITR-4 मा अब दुईवटासम्म घर सम्पत्ति मिल्छ)। कर वर्ष 2026-27 का रिटर्न Income-tax Rules, 2026 अन्तर्गत अझै सूचित हुन बाँकी छन्: भर्नुअघि फारमकै “कसले प्रयोग गर्न सक्दैन” सूची पढ्नुहोस्।",
  "it.n_ltcg": "सूचीकृत सेयर वा इक्विटी फन्डको सानो दीर्घकालीन गेन केही वर्ष ITR-1 र ITR-4 मा मिल्थ्यो; 2026-27 का लागि पक्का भएको छैन, त्यसैले ITR-2 सुरक्षित छनोट हो र फारमकै सूचीले निर्णय गर्छ।",
  "it.n_ae": "Section 44AE (मालवाहक गाडी) का आफ्नै सर्त छन्; अनुमानित फारम प्रयोग गर्नुअघि जाँच गर्नुहोस्।",
