  "nav.ca": "एकाउन्टेन्ट भ्युअर",
  "ca.mk": "मेरो एकाउन्टेन्टका लागि फाइल बनाउनुहोस् (हेर्न मात्र)",
  "ca.t": "मेरो एकाउन्टेन्टका लागि फाइल",
  "ca.intro": "एउटा व्यवसाय र अवधिलाई हेर्न मात्र मिल्ने एउटै फाइल (.nsca) मा राख्छ। यसलाई आफ्नो एकाउन्टेन्टलाई WhatsApp वा इमेलबाट पठाउनुहोस्। उहाँले ca.niveshsahayak.in मा खोलेर खाता पढ्नुहुन्छ, प्रश्न थप्नुहुन्छ र टिप्पणी तपाईंलाई फिर्ता पठाउनुहुन्छ।",
  "ca.notlive": "यो फाइल हस्तान्तरण हो, लाइभ साझा लगइन होइन। फाइल बनाउँदाको अवस्थामा खाता तपाईंको एकाउन्टेन्टले देख्नुहुन्छ। लाइभ लगइनका लागि तपाईंको खाता राख्ने सर्भर चाहिन्छ, र Nivesh Sahayak सँग कुनै छैन: तपाईंको खाता तपाईंकै डिभाइसमा रहन्छ। नयाँ इन्ट्रीका लागि नयाँ फाइल बनाउनुहोस्।",
  "ca.what": "के-के समावेश हुन्छ",
  "ca.earlier": "पहिलो मितिअघिका इन्ट्री पनि (सुरुको ब्यालेन्स र एजिङका लागि चाहिन्छ)",
  "ca.items": "खरिद र बिक्री दरसहितको आइटम सूची (स्टकका लागि चाहिन्छ)",
  "ca.extra": "तपाईंले टिक गरे मात्र",
