  "ca.codeh": "यो कोड आफ्नो सन्देशमा पठाउनुहोस्, वा फोनमा पढेर सुनाउनुहोस्। तपाईंको एकाउन्टेन्टले फाइलले देखाउने कोडसँग मिलाउनुहुन्छ, ताकि बाटोमा बदलिएको फाइल थाहा होस्।",
