  "ca.cT": "CA का टिप्पणी",
  "ca.cIntro": "तपाईंको एकाउन्टेन्टले प्रश्न र टिप्पणीको सानो फाइल (.nsca-comments) फिर्ता पठाउनुहुन्छ। हरेक प्रश्न त्यो इन्ट्रीको छेउमा हेर्न यहाँ लोड गर्नुहोस्। जवाफ दिनुहोस्, बन्द भनी चिन्ह लगाउनुहोस्, र फिर्ता पठाउन फाइल फेरि सेभ गर्नुहोस्।",
