  "ca.party": "पार्टी",
  "ca.screen": "स्क्रिन",
  "ca.general": "साधारण टिप्पणी",
  "cv.h1": "एकाउन्टेन्ट भ्युअर: तपाईंको क्लाइन्टले पठाएको खाताको फाइल खोल्नुहोस्",
  "cv.intro": "तपाईंको क्लाइन्टले कुनै अवधिको आफ्नो खाता एउटै फाइलमा राखेर WhatsApp वा इमेलबाट पठाउनुहुन्छ। यहाँ खोलेर पढ्नुहोस्: बाँकी, पार्टी, लेजर, डे बुक, GST हिसाब, अन्तिम खाता र हरेक डकुमेन्ट। खोज्नुहोस् र छान्नुहोस्, कुनै पनि इन्ट्रीमा प्रश्न सोध्नुहोस्, र आफ्ना टिप्पणी सानो फाइलमा फिर्ता पठाउनुहोस्। निःशुल्क, लगइन चाहिँदैन, र केही अपलोड हुँदैन: फाइल तपाईंको ब्राउजरभित्रै पढिन्छ।",
  "cv.drop": ".nsca फाइल यहाँ छोड्नुहोस्",
  "cv.choose": "फाइल छान्नुहोस्",
  "cv.dropnote": "फाइल यही डिभाइसमा रहन्छ। यहाँ केही सेभ हुँदैन र यहाँबाट तपाईंको क्लाइन्टको खाता बदल्न सकिँदैन।",
  "cv.nav.home": "सारांश",
  "cv.docs": "डकुमेन्ट",
  "cv.day": "डे बुक",
  "cv.fin": "अन्तिम खाता",
  "cv.gst": "GST हिसाब",
  "cv.cT": "प्रश्न र टिप्पणी",
  "cv.how.h": "यो कसरी चल्छ",
  "cv.how.1": "तपाईंको क्लाइन्टले Nivesh Sahayak खोलेर, मेरो डेटा, एकाउन्टेन्टलाई पठाउनुहोस् मा गई, एउटा व्यवसाय र अवधिका लागि \"मेरो एकाउन्टेन्टका लागि फाइल बनाउनुहोस्\" छान्नुहुन्छ।",
  "cv.how.2": "उहाँले फाइल (.nsca मा सकिने) र एउटै सन्देशमा छोटो जाँच कोड तपाईंलाई पठाउनुहुन्छ।",
  "cv.how.3": "तपाईं यो पेजमा फाइल खोल्नुहुन्छ। पेजले फाइल नबदलिएको हो कि होइन बताउँछ र मिलाउनका लागि क्लाइन्टले दिएको जाँच कोड टाइप गर्न दिन्छ।",
  "cv.how.4": "खाता पढ्नुहोस्, खोज्नुहोस्, र कुनै पनि डकुमेन्ट, डे बुक इन्ट्री वा स्क्रिनमा \"प्रश्न वा टिप्पणी थप्नुहोस्\" थिच्नुहोस्। तपाईंले लेखेको सबै यही ब्राउजरमा रहन्छ।",
  "cv.how.5": "सकिएपछि \"प्रश्न र टिप्पणी\" खोलेर सानो .nsca-comments फाइल फिर्ता पठाउनुहोस्। तपाईंको क्लाइन्टले लोड गरेर हरेक प्रश्न इन्ट्रीको छेउमा देख्नुहुन्छ। उहाँ जवाफ दिन सक्नुहुन्छ, र तपाईं ती जवाफ यहाँ लोड गर्न सक्नुहुन्छ।",
  "cv.live.h": "फाइल हस्तान्तरण, लाइभ लगइन होइन",
  "cv.live.p": "यो फाइल हस्तान्तरण हो। तपाईं क्लाइन्टको खातामा लगइन गर्नुहुन्न र उहाँले पछि गर्ने परिवर्तन देख्नुहुन्न। लाइभ साझा लगइनका लागि खाता राख्ने सर्भर चाहिन्छ, र Nivesh Sahayak सँग कुनै छैन: खाता क्लाइन्टकै डिभाइसमा रहन्छ। नयाँ अवधि वा सच्याइएपछिका लागि क्लाइन्टसँग नयाँ फाइल माग्नुहोस्।",
  "cv.safe.h": "फाइलमा के छ, र के छैन",
  "cv.safe.p": "तपाईंको क्लाइन्टले के राख्ने भनी टिक गर्नुहुन्छ। सामान्यतया फाइलमा एउटा व्यवसायका अवधिको अन्त्यसम्मका इन्ट्री, पार्टी र आइटम हुन्छन्। कोटेसन र अर्डर, तलब र स्टाफका रेकर्ड, फोन नम्बर र इमेल ठेगाना, र व्यवसायको बैंक खाताको विवरण क्लाइन्टले टिक नगरेसम्म छोडिन्छन्। तस्बिर, PIN र ब्याकअप सेटिङ कहिल्यै समावेश हुँदैनन्। फाइलमा चेकसम हुन्छ, त्यसैले कुनै परिवर्तन यो पेजमा देखिन्छ। फाइल बदलेर चेकसम फेरि निकाल्नेलाई चेकसमले रोक्न सक्दैन, त्यसैले क्लाइन्टले छुट्टै पठाएको जाँच कोडसँग मिलाउनुहोस्।",
  "cv.readonly": "यो फाइलको हेर्न मात्र मिल्ने दृश्य हो: यहाँ केही बदल्न वा सेभ गर्न सकिँदैन।",
  "cv.notfile": "यो Nivesh Sahayak को एकाउन्टेन्ट फाइल (.nsca) होइन।",
  "cv.iscomments": "यो टिप्पणी फाइल हो। पहिले खाताको फाइल (.nsca) खोल्नुहोस्, अनि \"प्रश्न र टिप्पणी\" बाट टिप्पणी लोड गर्नुहोस्।",
  "cv.newer": "यो फाइल नयाँ संस्करणले बनाएको हो। यो पेज रिलोड गरेर फेरि प्रयास गर्नुहोस्।",
  "cv.nostore": "तपाईंका टिप्पणी यो ब्राउजरमा राख्न सकिएन। अहिले नै टिप्पणी फाइल सेभ गर्नुहोस्।",
