  "cv.cIntro": "तपाईंका प्रश्न र टिप्पणी। यी यो फाइलका लागि यही ब्राउजरमा राखिन्छन्। \"टिप्पणी फाइल सेभ गर्नुहोस्\" थिचेर क्लाइन्टलाई पठाउनुहोस्; उहाँले लोड गरेर हरेक प्रश्न इन्ट्रीको छेउमा देख्नुहुन्छ।",
