  "hm.h.cash.good": "राम्रो जगेडा छ। यसलाई राख्नुहोस्, र अर्को महिनाका ठूला भुक्तानी ध्यानमा राख्नुहोस्।",
  "hm.h.cash.ok": "जगेडा पातलो छ। म्याद नाघेको पैसा उठाउनुहोस् र अहिलेलाई ठूला खरिद नगर्नुहोस्।",
