  "hm.h.recv.good": "पैसा छिटो फर्कन्छ। ढिला गर्नेहरूलाई सम्झाइरहनुहोस्।",
  "hm.h.recv.ok": "पैसा ढिलो फर्कन्छ। बाँकी स्क्रिनबाट हरेक हप्ता रिमाइन्डर पठाउनुहोस्।",
  "hm.h.recv.low": "पैसा ग्राहकसँग धेरै लामो समय अड्किएको छ। पहिले सबैभन्दा पुराना बिल उठाउनुहोस् र नयाँ अर्डरअघि केही भुक्तानी माग्नुहोस्।",
