  "hm.h.margin.ok": "मार्जिन पातलो छ वा घट्दै छ। आफ्नो बिक्री मूल्य र मुख्य आइटमको लागत जाँच गर्नुहोस्।",
  "hm.h.margin.low": "लगभग केही बच्दैन। मूल्य बढाउनुहोस्, लागत घटाउनुहोस् वा घाटा हुने आइटम बेच्न बन्द गर्नुहोस्।",
  "hm.h.margin.rule": "पछिल्ला 3 पूरा महिनाको बिक्रीबाट खरिद र खर्च घटाएको, बिक्रीको भागको रूपमा। 15 वा बढी भए 100, 0 वा कम भए 0; अघिल्ला 3 महिनाभन्दा 5 अङ्कभन्दा बढी घटे 20 अङ्क काटिन्छ। हातमा भएको स्टक गनिँदैन।",
  "hm.h.creep": "खर्च बढ्दै",
  "hm.h.creep.how": "गएको महिना तपाईंको खर्च {l} थियो; त्योभन्दा अघिका 3 महिनाको औसत {a}। यो {p}% को परिवर्तन हो।",
