  "hm.h.creep.low": "खर्च एक्कासि बढ्यो। बढेको शीर्षक खोज्नुहोस्, र त्यो एक पटकको बिल होइन कि जाँच गर्नुहोस्।",
  "hm.h.creep.rule": "पछिल्लो पूरा महिनाको खर्चलाई त्योभन्दा अघिका 3 महिनाको औसतसँग तुलना। 5% वा कम बढे 100, 40% वा बढी बढे 0। एक पटकको ठूलो बिलले एक महिनाका लागि यसलाई घटाउँछ।",
